from functools import lru_cache

def compute_nmin(a):
    n = len(a)
    INF = 10**9
    best = INF
    # Enumerate feasible (x0, r0)
    for x0 in range(a[0] + 1):
        for r0 in range(a[0] - x0 + 1):
            # x0 >= 0, r0 >= 0, x0 + r0 <= a[0]
            # Define DP for vertices 1..n-1
            @lru_cache(maxsize=None)
            def F(i, prev_x, prev_rpos):
                # returns minimal sum of x[i]..x[n-1] given prev_x = x[i-1], prev_rpos = (r[i-1] > 0)
                if i == n - 1:
                    # last vertex: choose r_{n-1} subject to independence with prev_rpos and r0
                    min_cost = INF
                    max_r = a[i] - prev_x
                    if max_r < 0:
                        return INF
                    for r_i in range(max_r + 1):
                        if prev_rpos and r_i > 0:
                            continue
                        if r0 > 0 and r_i > 0:
                            # independence with r0
                            continue
                        x_i = a[i] - prev_x - r_i
                        if x_i < 0:
                            continue
                        # cost contribution is x_i
                        min_cost = min(min_cost, x_i)
                    return min_cost
                else:
                    min_cost = INF
                    max_r = a[i] - prev_x
                    if max_r < 0:
                        return INF
                    for r_i in range(max_r + 1):
                        if prev_rpos and r_i > 0:
                            continue
                        x_i = a[i] - prev_x - r_i
                        if x_i < 0:
                            continue
                        cost = x_i + F(i + 1, x_i, r_i > 0)
                        if cost < min_cost:
                            min_cost = cost
                    return min_cost
            total = x0 + F(1, x0, r0 > 0)
            if total < best:
                best = total
    # If no feasible construction found (shouldn't happen), return 0
    if best == INF:
        best = 0
    return best

N_max_ops = compute_nmax(a)
N_min_ops = compute_nmin(a)
# Sanity checks: bounds
# N_min cannot exceed N_max
if N_min_ops > N_max_ops:
    # Numerical inconsistency, reject instance
    return (False, None)
# Both nonnegative
if N_max_ops < 0 or N_min_ops < 0:
    return (False, None)
# Final answer: Kumar collects exactly one coin per operation by the rule statement
answer = 1000 * N_max_ops + N_min_ops
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

